import{_ as l,o,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const C=JSON.parse('{"title":"2019-04-16:: Crimson SeaStor OSD Weekly Meeting","description":"","frontmatter":{"title":"2019-04-16:: Crimson SeaStor OSD Weekly Meeting","date":"2019-04-16T00:00:00.000Z","updated":"2019-04-17T00:00:00.000Z","tags":["Ceph","Crimson","OSD","Performance Optimization","Distributed Storage"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-04-16_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","filePath":"posts/2019/2019-04-16_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md","lastUpdated":1780460162000}'),n={name:"posts/2019/2019-04-16_-_-_Crimson_SeaStor_OSD_Weekly_Meeting.md"};function s(e,i,u,a,_,g){return o(),t("div",null,[...i[0]||(i[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年4月16日 <strong>参会人员</strong>： [未提供具体名单，请补充] <strong>会议主题</strong>： Ceph Crimson项目进展及讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. CFX Austin厨房支持费用问题</strong></p><ul><li>项目方要求支付费用以支持Crimson项目的CFX Austin厨房。</li><li>讨论了支付方式和费用问题。</li></ul><p><strong>2. Crimson项目进展</strong></p><ul><li><strong>Crimson项目测试</strong>： <ul><li>已经完成了Crimson项目的测试，测试结果显示性能有所提升。</li><li>目前正在集成，预计下周完成。</li><li>已完成Crimson编译，并进行了初步测试。</li></ul></li><li><strong>性能优化</strong>： <ul><li>讨论了Crimson项目的性能优化，包括： <ul><li>执行阶段优化：通过减少参数传递和任务调度，提高性能。</li><li>异步编程优化：利用Future和Continuation提高性能。</li></ul></li></ul></li><li><strong>性能监控</strong>： <ul><li>讨论了性能监控问题，包括： <ul><li>引入新的性能计数器，用于测量批处理消息的平均大小。</li><li>开发人员将实现新的性能计数器。</li></ul></li></ul></li></ul><p><strong>3. 其他讨论</strong></p><ul><li><strong>Crimson项目与经典OSD的兼容性</strong>： <ul><li>讨论了Crimson项目与经典OSD的兼容性问题。</li><li>认为Crimson项目与经典OSD的兼容性是重要的。</li></ul></li><li><strong>Crimson项目与BlueStore的集成</strong>： <ul><li>讨论了Crimson项目与BlueStore的集成问题。</li><li>认为短期内将采用BlueStore进行集成。</li></ul></li><li><strong>Crimson项目与RBD的集成</strong>： <ul><li>讨论了Crimson项目与RBD的集成问题。</li><li>认为Crimson项目与RBD的集成是长期目标。</li></ul></li></ul><p><strong>4. 行动计划</strong></p><ul><li><strong>Crimson项目测试</strong>： <ul><li>完成Crimson项目的集成，并进行测试。</li></ul></li><li><strong>性能优化</strong>： <ul><li>继续进行性能优化，提高Crimson项目的性能。</li></ul></li><li><strong>性能监控</strong>： <ul><li>开发新的性能计数器，用于监控Crimson项目的性能。</li></ul></li></ul><p><strong>5. 其他</strong></p><ul><li>新同事Ron将加入Crimson项目团队。</li><li>讨论了Crimson项目与经典OSD的兼容性问题。</li></ul><p><strong>备注</strong>：</p><ul><li>部分内容涉及Ceph相关技术，如Crimson、BlueStore、RBD、Future、Continuation等。</li><li>会议中使用了部分英文关键词，如Crimson、BlueStore、RBD、Future、Continuation等。</li></ul>',15)])])}const p=l(n,[["render",s]]);export{C as __pageData,p as default};
